import { getCurrentThemeSlug } from "../features/game/storage";
import { listThemes } from "../themes";
import { clear, h } from "./dom";
import { renderInviteButton } from "./invite";
import type { Cleanup } from "./router";

function renderContinueCard(): HTMLElement | null {
  const slug = getCurrentThemeSlug();
  if (!slug) return null;
  return h(
    "a",
    {
      href: `#/play/${encodeURIComponent(slug)}`,
      class: "continue-card press",
      "data-testid": "continue-game",
    },
    h(
      "span",
      null,
      h("span", { class: "continue-card__title" }, "Continue your game"),
      h(
        "span",
        { class: "continue-card__sub" },
        "Your card is right where you left it.",
      ),
    ),
    h("span", { class: "continue-card__arrow", "aria-hidden": "true" }, "→"),
  );
}

export function mountHome(root: HTMLElement): Cleanup {
  const themes = listThemes();
  root.appendChild(
    h(
      "main",
      { class: "screen screen--home" },
      h("p", { class: "eyebrow" }, "Visual Bingo"),
      h("h1", { class: "h1" }, "Spot it. Tap it. Bingo."),
      h(
        "p",
        { class: "lead" },
        "A real-world scavenger hunt on a bingo card. Pick a theme, deal a card, and go for a walk.",
      ),
      h("div", { class: "pt-10" }, renderContinueCard()),
      h("h2", { class: "h2" }, "Themes"),
      h(
        "ul",
        { class: "theme-list" },
        ...themes.map((t) => {
          const activeTileCount = t.tiles.filter((x) => x.active).length;
          return h(
            "li",
            null,
            h(
              "a",
              {
                href: `#/play/${encodeURIComponent(t.slug)}`,
                class: "theme-card press",
                "data-testid": `theme-${t.slug}`,
              },
              h(
                "span",
                { class: "theme-card__icon", "aria-hidden": "true" },
                "🐕",
              ),
              h(
                "span",
                { class: "theme-card__body" },
                h("span", { class: "theme-card__name" }, t.name),
                h("span", { class: "theme-card__desc" }, t.description),
                h(
                  "span",
                  { class: "theme-card__meta" },
                  `${activeTileCount} tiles${t.recommendedAge ? ` · ${t.recommendedAge}` : ""}`,
                ),
              ),
            ),
          );
        }),
      ),
      renderInviteButton(),
      h("div", { class: "spacer" }),
      h(
        "p",
        { class: "hint" },
        "Add to your home screen for the best experience.",
      ),
    ),
  );
  return () => clear(root);
}
