import type { GameModeId, SlotId, Theme, Tile } from "../../domain/types";
import {
  migrateGameState,
  newGame,
  reSpinSlot,
  toggleSlot,
  validateRestoredState,
  type GameState,
} from "./state";
import {
  indexedDbStorage,
  setCurrentThemeSlug,
  type GameStorage,
} from "./storage";

export type GamePhase = "loading" | "options" | "playing";

export interface GameSnapshot {
  phase: GamePhase;
  state: GameState | null;
  /** True after the completing transition until the consumer clears it. */
  justCompleted: boolean;
  error: string | null;
}

export interface GameController {
  tilesById: Map<string, Tile>;
  getSnapshot(): GameSnapshot;
  subscribe(listener: (snap: GameSnapshot) => void): () => void;
  start(mode: GameModeId, freeCenter: boolean): void;
  toggle(slotId: SlotId): void;
  respin(slotId: SlotId): { newTile: Tile } | null;
  abandon(): void;
  clearJustCompleted(): void;
  destroy(): void;
}

/**
 * Wires pure game state to persistence and notifies subscribers after every
 * change. Framework-free port of the original React `useGame` hook: same
 * restore, persist-on-mutation, and flush-on-background behaviour.
 */
export function createGame(
  theme: Theme,
  storage: GameStorage = indexedDbStorage,
): GameController {
  const tilesById = new Map(theme.tiles.map((t) => [t.id, t]));
  const listeners = new Set<(snap: GameSnapshot) => void>();
  let snap: GameSnapshot = {
    phase: "loading",
    state: null,
    justCompleted: false,
    error: null,
  };
  let cancelled = false;

  function set(patch: Partial<GameSnapshot>) {
    snap = { ...snap, ...patch };
    for (const l of listeners) l(snap);
  }

  // Queue the write before the synchronous re-render so the IndexedDB request
  // is in flight as early as possible (matters when the user navigates right
  // after a tap; WebKit aborts pending transactions on unload).
  function persist(next: GameState) {
    const saving = storage.save(next);
    set({ state: next });
    saving.catch((e) => set({ error: String(e) }));
  }

  // Restore the current game for this theme.
  (async () => {
    const id = storage.getCurrentGameId();
    if (!id) return set({ phase: "options" });
    try {
      const raw = await storage.load(id);
      if (cancelled) return;
      const loaded = raw ? migrateGameState(raw) : null;
      if (
        loaded &&
        loaded.game.themeId === theme.id &&
        validateRestoredState(loaded, tilesById)
      ) {
        set({ state: loaded, phase: "playing" });
        // Persist the migrated shape so future loads skip migration.
        storage.save(loaded).catch(() => {});
      } else {
        console.warn(
          "dog-bingo: save could not be restored; starting fresh",
          id,
        );
        storage.setCurrentGameId(null);
        setCurrentThemeSlug(null);
        set({ phase: "options" });
      }
    } catch {
      if (!cancelled) set({ phase: "options" });
    }
  })();

  // Re-save when the app is backgrounded or the page is going away, so an
  // OS killing the tab right after a tap cannot lose the last mutation.
  const flush = () => {
    const cur = snap.state;
    if (!cur) return;
    storage.flushSync?.(cur);
    storage.save(cur).catch(() => {});
  };
  const onVisibility = () => {
    if (document.visibilityState === "hidden") flush();
  };
  window.addEventListener("pagehide", flush);
  document.addEventListener("visibilitychange", onVisibility);

  return {
    tilesById,
    getSnapshot: () => snap,
    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    start(mode, freeCenter) {
      try {
        const s = newGame({ theme, mode, freeCenter });
        storage.setCurrentGameId(s.game.id);
        setCurrentThemeSlug(theme.slug);
        // Ask the browser not to evict our IndexedDB under storage pressure.
        try {
          void navigator.storage?.persist?.();
        } catch {
          /* unsupported */
        }
        const saving = storage.save(s);
        set({ justCompleted: false, error: null, state: s, phase: "playing" });
        saving.catch((e) => set({ error: String(e) }));
      } catch (e) {
        set({ error: e instanceof Error ? e.message : String(e) });
      }
    },
    toggle(slotId) {
      const cur = snap.state;
      if (!cur) return;
      const r = toggleSlot(cur, slotId);
      if (r.state !== cur) persist(r.state);
      if (r.justCompleted) set({ justCompleted: true });
    },
    respin(slotId) {
      const cur = snap.state;
      if (!cur) return null;
      try {
        const r = reSpinSlot(cur, slotId, theme.tiles);
        persist(r.state);
        return { newTile: r.newTile };
      } catch (e) {
        set({ error: e instanceof Error ? e.message : String(e) });
        return null;
      }
    },
    abandon() {
      const cur = snap.state;
      if (cur) storage.remove(cur.game.id).catch(() => {});
      storage.setCurrentGameId(null);
      setCurrentThemeSlug(null);
      set({ state: null, justCompleted: false, phase: "options" });
    },
    clearJustCompleted() {
      if (snap.justCompleted) set({ justCompleted: false });
    },
    destroy() {
      cancelled = true;
      listeners.clear();
      window.removeEventListener("pagehide", flush);
      document.removeEventListener("visibilitychange", onVisibility);
    },
  };
}
