import type { Tile } from "../domain/types";
import { h } from "./dom";
import { openOverlay, type Overlay } from "./overlay";
import { renderTileArt } from "./tile-art";

/** Bottom-sheet with the tile's art and identification notes. */
export function openTileDetail(tile: Tile, onClose: () => void): Overlay {
  const facts: [string, string | undefined][] = [
    ["How to spot it", tile.identificationTips],
    ["Typical size", tile.sizeNotes],
    ["Coat & color", tile.coatNotes],
  ];

  let overlay: Overlay | null = null;

  const content = [
    h(
      "div",
      { class: "sheet-header" },
      h(
        "span",
        { class: `chip chip--${tile.rarityCategory}` },
        tile.rarityCategory,
      ),
      h(
        "button",
        {
          type: "button",
          class: "close-btn",
          "aria-label": "Close",
          onClick: () => overlay?.close(),
        },
        "×",
      ),
    ),
    h("div", { class: "sheet-art" }, renderTileArt(tile, "detail")),
    h("h2", { id: "tile-detail-title", class: "sheet-title" }, tile.name),
    tile.description ? h("p", { class: "sheet-desc" }, tile.description) : null,
    h(
      "dl",
      { class: "facts" },
      ...facts
        .filter(([, v]) => Boolean(v))
        .map(([k, v]) =>
          h(
            "div",
            { class: "facts__row" },
            h("dt", { class: "facts__dt" }, k),
            h("dd", { class: "facts__dd" }, v ?? ""),
          ),
        ),
    ),
  ].filter((n): n is NonNullable<typeof n> => n !== null);

  overlay = openOverlay({
    testid: "tile-detail",
    labelledBy: "tile-detail-title",
    placement: "bottom",
    closeOnBackdrop: true,
    closeOnEscape: true,
    content,
    onClose,
  });
  return overlay;
}
