import type { GameModeId } from "../domain/types";
import { h } from "./dom";
import { openOverlay, type Overlay } from "./overlay";
import { prefersReducedMotion } from "./reduced-motion";

export interface CompletionProps {
  mode: GameModeId;
  found: number;
  total: number;
  elapsedMs: number;
  respinsUsed: number;
  onPlayAgain(): void;
  onNewCard(): void;
  onThemes(): void;
}

const COLORS = ["#e8743b", "#4caf7d", "#8a5cf6", "#3b82f6", "#fbbf24"];
const PIECES = 36;

function fmt(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000));
  const m = Math.floor(s / 60);
  return m > 0 ? `${m}m ${s % 60}s` : `${s}s`;
}

/** Win overlay. Cannot be dismissed except through its three actions. */
export function openCompletion(p: CompletionProps): Overlay {
  const reduced = prefersReducedMotion();
  const headline = p.mode === "bingo" ? "BINGO!" : "CARD COMPLETE!";
  const respinWord = p.respinsUsed === 1 ? "re-spin" : "re-spins";

  const confetti = reduced
    ? null
    : h(
        "div",
        { class: "confetti", "aria-hidden": "true" },
        ...Array.from({ length: PIECES }, (_, i) =>
          h("span", {
            class: "confetti__piece",
            style: {
              left: `${(i * 37) % 100}%`,
              background: COLORS[i % COLORS.length],
              animation: `confetti-fall ${2.2 + (i % 5) * 0.3}s linear ${(i % 7) * 0.15}s both`,
            },
          }),
        ),
      );

  return openOverlay({
    testid: "completion",
    label: headline,
    placement: "center",
    closeOnBackdrop: false,
    closeOnEscape: false,
    // Let the winning tile's stamp finish before the overlay rises.
    backdropStyle: reduced
      ? undefined
      : { animation: "rise 300ms ease-out 450ms both" },
    behind: confetti ? [confetti] : [],
    content: [
      h("p", { class: "completion__emoji", "aria-hidden": "true" }, "🎉"),
      h("h2", { class: "completion__title" }, headline),
      h(
        "p",
        { class: "muted pt-2" },
        `${p.found} / ${p.total} found · ${fmt(p.elapsedMs)} · ${p.respinsUsed} ${respinWord} used`,
      ),
      h(
        "div",
        { class: "stack pt-6" },
        h(
          "button",
          {
            type: "button",
            class: "btn btn--primary press",
            onClick: p.onPlayAgain,
          },
          "Play again",
        ),
        h(
          "button",
          {
            type: "button",
            class: "btn btn--muted-bg press",
            onClick: p.onNewCard,
          },
          "Change game options",
        ),
        h(
          "button",
          { type: "button", class: "btn btn--text", onClick: p.onThemes },
          "Back to themes",
        ),
      ),
    ],
  });
}
