import type { Theme, Tile } from "../domain/types";
import { GAME_MODES, progress } from "../domain/win-conditions";
import {
  createGame,
  type GameController,
  type GamePhase,
  type GameSnapshot,
} from "../features/game/controller";
import {
  feedbackFound,
  feedbackUnfound,
  isMuted,
  setMuted,
  subscribeMuted,
} from "../features/game/feedback";
import { createCardGrid, type CardGrid } from "./card-grid";
import { openCompletion } from "./completion";
import { clear, h } from "./dom";
import { renderOptions, type OptionsView } from "./options";
import type { Overlay } from "./overlay";
import type { Cleanup } from "./router";
import { openTileDetail } from "./tile-detail";

/** Play route: loading → options → playing, driven by the game controller. */
export function mountPlay(root: HTMLElement, theme: Theme): Cleanup {
  const game = createGame(theme);
  let renderedPhase: GamePhase | null = null;
  let subCleanup: Cleanup | null = null;
  let optionsView: OptionsView | null = null;
  let shell: PlayShell | null = null;

  function render(snap: GameSnapshot) {
    const phase: GamePhase =
      snap.phase === "playing" && !snap.state ? "options" : snap.phase;
    if (phase !== renderedPhase) {
      subCleanup?.();
      subCleanup = null;
      optionsView = null;
      shell = null;
      clear(root);
      renderedPhase = phase;
      if (phase === "loading") {
        root.appendChild(
          h(
            "main",
            { class: "screen screen--center" },
            h("p", { class: "muted font-bold" }, "Loading…"),
          ),
        );
      } else if (phase === "options") {
        optionsView = renderOptions({
          theme,
          error: snap.error,
          onStart: (mode, freeCenter) => game.start(mode, freeCenter),
        });
        root.appendChild(optionsView.el);
      } else {
        shell = createPlayShell(root, theme, game);
        subCleanup = shell.destroy;
      }
    }
    if (phase === "options") optionsView?.setError(snap.error);
    if (phase === "playing" && snap.state) shell?.update(snap);
  }

  const unsubscribe = game.subscribe(render);
  render(game.getSnapshot());

  return () => {
    unsubscribe();
    subCleanup?.();
    game.destroy();
    clear(root);
  };
}

interface PlayShell {
  update(snap: GameSnapshot): void;
  destroy(): void;
}

function createPlayShell(
  root: HTMLElement,
  theme: Theme,
  game: GameController,
): PlayShell {
  let detail: Overlay | null = null;
  let completion: Overlay | null = null;
  let dismissedGameId: string | null = null;
  let confirmNew = false;

  function handleToggle(slotId: string) {
    const st = game.getSnapshot().state;
    if (st && st.game.status === "active") {
      const slot = st.card.slots.find((x) => x.id === slotId);
      if (slot && !slot.isFree) {
        if (slot.isFound) feedbackUnfound();
        else feedbackFound();
      }
    }
    game.toggle(slotId);
  }

  function showDetail(tile: Tile) {
    detail?.close();
    detail = openTileDetail(tile, () => {
      detail = null;
    });
  }

  // --- header ---
  const modeLabel = h("p", { class: "play-mode" });
  const progressPill = h("span", {
    class: "pill pill--surface",
    "data-testid": "progress",
  });
  const respinsPill = h("span", {
    class: "pill",
    "data-testid": "respins",
    "aria-live": "polite",
  });
  const header = h(
    "header",
    { class: "play-header" },
    h("div", null, h("h1", { class: "play-title" }, theme.name), modeLabel),
    h("div", { class: "pills" }, progressPill, respinsPill),
  );

  // --- grid ---
  const gridEl = h("div", {
    class: "card-grid",
    role: "grid",
    "aria-label": "Bingo card",
  });
  const grid: CardGrid = createCardGrid(gridEl, {
    tilesById: game.tilesById,
    allTiles: theme.tiles,
    onToggle: handleToggle,
    onInfo: showDetail,
    onReSpin: (slotId) => game.respin(slotId),
  });

  // --- footer ---
  const muteBtn = h("button", {
    type: "button",
    class: "icon-btn",
    "data-testid": "mute",
    onClick: () => setMuted(!isMuted()),
  });
  function renderMute() {
    const muted = isMuted();
    muteBtn.setAttribute("aria-pressed", String(muted));
    muteBtn.setAttribute("aria-label", muted ? "Unmute sounds" : "Mute sounds");
    muteBtn.textContent = muted ? "🔇" : "🔊";
  }
  renderMute();
  const unsubMute = subscribeMuted(renderMute);

  const newGameSlot = h("span", { class: "new-game-slot" });
  function renderNewGame() {
    clear(newGameSlot);
    if (!confirmNew) {
      newGameSlot.appendChild(
        h(
          "button",
          {
            type: "button",
            class: "btn btn--text text-sm",
            "data-testid": "new-game",
            onClick: () => {
              confirmNew = true;
              renderNewGame();
            },
          },
          "New card",
        ),
      );
      return;
    }
    newGameSlot.appendChild(
      h(
        "span",
        { class: "confirm-inline" },
        h("span", { class: "muted" }, "Abandon card?"),
        h(
          "button",
          {
            type: "button",
            class: "btn btn--danger",
            "data-testid": "confirm-new-game",
            onClick: () => {
              confirmNew = false;
              game.abandon();
            },
          },
          "Yes",
        ),
        h(
          "button",
          {
            type: "button",
            class: "btn btn--text",
            onClick: () => {
              confirmNew = false;
              renderNewGame();
            },
          },
          "No",
        ),
      ),
    );
  }
  renderNewGame();

  const footer = h(
    "footer",
    { class: "play-footer" },
    h("a", { href: "#/", class: "btn btn--text text-sm" }, "← Themes"),
    muteBtn,
    newGameSlot,
  );

  const errorEl = h("p", {
    role: "alert",
    class: "alert alert--play",
    hidden: true,
  });

  root.appendChild(
    h(
      "main",
      { class: "screen screen--play" },
      header,
      h("div", { class: "grid-area" }, gridEl),
      footer,
      errorEl,
    ),
  );

  return {
    update(snap) {
      const state = snap.state;
      if (!state) return;
      const prog = progress(state.card);
      const respins = state.player.respinsRemaining;
      const completed = state.game.status === "completed";

      modeLabel.textContent =
        state.game.gameMode === "full_card"
          ? (theme.fullCardLabel ?? GAME_MODES.full_card.label)
          : GAME_MODES.bingo.label;
      progressPill.textContent = `${prog.found} / ${prog.total}`;
      respinsPill.textContent = `Re-spins: ${respins}`;
      respinsPill.className = `pill ${respins > 0 ? "pill--accent" : "pill--muted"}`;

      grid.update(state.card, completed ? 0 : respins);

      errorEl.textContent = snap.error ?? "";
      errorEl.hidden = !snap.error;

      const showCompletion = completed && dismissedGameId !== state.game.id;
      if (showCompletion && !completion) {
        const gameId = state.game.id;
        const dismiss = () => {
          dismissedGameId = gameId;
          completion?.close();
          completion = null;
        };
        completion = openCompletion({
          mode: state.game.gameMode,
          found: prog.found,
          total: prog.total,
          elapsedMs:
            (state.completedAt ?? state.game.endedAt ?? 0) -
            (state.game.startedAt ?? state.game.createdAt),
          respinsUsed: state.game.config.respins - respins,
          onPlayAgain: () => {
            dismiss();
            game.start(state.game.gameMode, state.game.config.freeCenter);
          },
          onNewCard: () => {
            dismiss();
            game.abandon();
          },
          onThemes: () => {
            dismiss();
            location.hash = "#/";
          },
        });
      } else if (!showCompletion && completion) {
        completion.close();
        completion = null;
      }
    },
    destroy() {
      unsubMute();
      grid.destroy();
      detail?.close();
      completion?.close();
    },
  };
}
