import { canReSpin } from "../domain/respin";
import type { Card, Tile } from "../domain/types";
import { createTileCell, type TileCell, type TileCellDeps } from "./tile-cell";

export interface CardGridDeps extends TileCellDeps {
  tilesById: Map<string, Tile>;
  allTiles: readonly Tile[];
}

export interface CardGrid {
  el: HTMLElement;
  update(card: Card, respinsRemaining: number): void;
  destroy(): void;
}

/**
 * Keeps one persistent element per slot so CSS animations and the re-spin
 * timers survive state updates. Rebuilds only when the slot set changes.
 */
export function createCardGrid(el: HTMLElement, deps: CardGridDeps): CardGrid {
  const cells = new Map<string, TileCell>();
  let cardId: string | null = null;

  function rebuild(card: Card) {
    for (const c of cells.values()) c.destroy();
    cells.clear();
    el.replaceChildren();
    cardId = card.id;
  }

  return {
    el,
    update(card, respinsRemaining) {
      if (card.id !== cardId) rebuild(card);
      el.style.gridTemplateColumns = `repeat(${card.columns}, minmax(0, 1fr))`;
      el.style.gridTemplateRows = `repeat(${card.rows}, minmax(0, 1fr))`;

      // Presentation-only: faces to cycle during a spin. Never decides the outcome.
      const onCard = new Set(card.slots.map((s) => s.tileId));
      const spinCandidates = deps.allTiles
        .filter((t) => t.active && !onCard.has(t.id))
        .slice(0, 12);

      for (const slot of card.slots) {
        const tile = slot.tileId
          ? (deps.tilesById.get(slot.tileId) ?? null)
          : null;
        const props = {
          slot,
          tile,
          canReSpin: canReSpin(slot, respinsRemaining),
          spinCandidates,
        };
        let cell = cells.get(slot.id);
        if (!cell) {
          cell = createTileCell(props, deps);
          cells.set(slot.id, cell);
          el.appendChild(cell.el);
        } else {
          cell.update(props);
        }
      }
    },
    destroy() {
      for (const c of cells.values()) c.destroy();
      cells.clear();
      el.replaceChildren();
    },
  };
}
