import type { GameModeId, Theme } from "../domain/types";
import { clear, h } from "./dom";

export interface OptionsProps {
  theme: Theme;
  error: string | null;
  onStart(mode: GameModeId, freeCenter: boolean): void;
}

export interface OptionsView {
  el: HTMLElement;
  setError(error: string | null): void;
}

const MODE_BLURB: Record<GameModeId, string> = {
  full_card: "Find every tile on the card. Best for a long walk.",
  bingo: "Any full row, column, or diagonal wins. Quick game.",
};

/** Pre-game options: game mode, and free-centre when the card has a centre. */
export function renderOptions(p: OptionsProps): OptionsView {
  const { theme } = p;
  let mode: GameModeId = theme.defaultGameMode;
  let freeCenter = theme.config.freeCenter;
  const columns = theme.defaultCardColumns;
  const rows = theme.defaultCardRows;
  const hasCenter = columns % 2 === 1 && rows % 2 === 1;

  const modeButtons = new Map<GameModeId, HTMLButtonElement>();
  const radioGroup = h("div", {
    class: "radio-group",
    role: "radiogroup",
    "aria-label": "Game mode",
  });

  function renderModes() {
    clear(radioGroup);
    const modes: { id: GameModeId; label: string }[] = [
      { id: "full_card", label: theme.fullCardLabel ?? "Full Card" },
      { id: "bingo", label: "Bingo" },
    ];
    for (const m of modes) {
      const btn = h(
        "button",
        {
          type: "button",
          role: "radio",
          "aria-checked": String(mode === m.id),
          "data-testid": `mode-${m.id}`,
          class: "radio-card press",
          onClick: () => {
            mode = m.id;
            for (const [id, b] of modeButtons)
              b.setAttribute("aria-checked", String(id === mode));
          },
        },
        h("span", { class: "radio-card__label" }, m.label),
        h("span", { class: "radio-card__blurb" }, MODE_BLURB[m.id]),
      );
      modeButtons.set(m.id, btn);
      radioGroup.appendChild(btn);
    }
  }
  renderModes();

  const freeSub = h("span", { class: "toggle-row__sub" });
  function renderFreeSub() {
    const tiles = columns * rows - (freeCenter ? 1 : 0);
    freeSub.textContent = `${columns}×${rows} card, ${tiles} tiles to find`;
  }
  renderFreeSub();

  const freeRow = hasCenter
    ? h(
        "label",
        { class: "toggle-row" },
        h(
          "span",
          null,
          h("span", { class: "toggle-row__title" }, "Free center space"),
          freeSub,
        ),
        h("input", {
          type: "checkbox",
          class: "checkbox",
          checked: freeCenter,
          onChange: (e: Event) => {
            freeCenter = (e.target as HTMLInputElement).checked;
            renderFreeSub();
          },
        }),
      )
    : null;

  const errorEl = h(
    "p",
    { role: "alert", class: "alert", hidden: !p.error },
    p.error ?? "",
  );

  const el = h(
    "main",
    { class: "screen screen--options" },
    h("a", { href: "#/", class: "btn btn--text btn--back" }, "← Themes"),
    h("h1", { class: "h1 h1--sm" }, theme.name),
    h("p", { class: "muted pt-1" }, theme.description),
    h("h2", { class: "h2 pt-8" }, "Game mode"),
    radioGroup,
    freeRow,
    errorEl,
    h("div", { class: "spacer" }),
    h(
      "button",
      {
        type: "button",
        class: "btn btn--primary btn--cta press",
        "data-testid": "start-game",
        onClick: () => p.onStart(mode, freeCenter),
      },
      "Deal my card",
    ),
  );

  return {
    el,
    setError(error) {
      errorEl.textContent = error ?? "";
      errorEl.hidden = !error;
    },
  };
}
