import QRCode from "qrcode";
import { h } from "./dom";
import { openOverlay, type Overlay } from "./overlay";

/** The URL friends should open: this page without the hash, so subpath hosting works. */
function shareUrl(): string {
  return location.href.split("#")[0];
}

async function openInviteDialog(): Promise<Overlay | null> {
  const url = shareUrl();
  let dataUrl: string;
  try {
    dataUrl = await QRCode.toDataURL(url, {
      width: 640,
      margin: 1,
      color: { dark: "#2b211a", light: "#ffffff" },
    });
  } catch (e) {
    console.error("dog-bingo: QR generation failed", e);
    return null;
  }

  let overlay: Overlay | null = null;
  const shareBtn = h(
    "button",
    {
      type: "button",
      class: "btn btn--primary press",
      onClick: async () => {
        if (navigator.share) {
          try {
            await navigator.share({
              title: "Dog Bingo",
              text: "Play Dog Bingo with me!",
              url,
            });
          } catch {
            /* cancelled */
          }
          return;
        }
        try {
          await navigator.clipboard.writeText(url);
          shareBtn.textContent = "Link copied!";
        } catch {
          /* clipboard unavailable */
        }
      },
    },
    "Share link",
  );

  overlay = openOverlay({
    testid: "invite-dialog",
    labelledBy: "invite-title",
    placement: "center",
    closeOnBackdrop: true,
    closeOnEscape: true,
    content: [
      h(
        "h2",
        { id: "invite-title", class: "overlay__title" },
        "Invite a friend",
      ),
      h(
        "p",
        { class: "muted text-sm pt-1" },
        "Scan to open the game on another phone. You each play your own card — first to finish wins!",
      ),
      h("img", {
        src: dataUrl,
        alt: `QR code linking to ${url}`,
        class: "qr-img",
      }),
      h("p", { class: "invite-url" }, url),
      h(
        "div",
        { class: "stack pt-4" },
        shareBtn,
        h(
          "button",
          {
            type: "button",
            class: "btn btn--text",
            "aria-label": "Close",
            onClick: () => overlay?.close(),
          },
          "Close",
        ),
      ),
    ],
  });
  return overlay;
}

/** The "Invite a friend" button for the home screen. */
export function renderInviteButton(): HTMLElement {
  return h(
    "button",
    {
      type: "button",
      class: "btn btn--surface btn--invite press",
      "data-testid": "invite",
      onClick: () => void openInviteDialog(),
    },
    h("span", { "aria-hidden": "true" }, "📱"),
    " Invite a friend",
  );
}
