import { getThemeBySlug } from "../themes";
import { clear, h } from "./dom";
import { mountHome } from "./home";
import { mountPlay } from "./play";

export type Cleanup = () => void;

type Route = { name: "home" } | { name: "play"; slug: string };

function parseRoute(hash: string): Route {
  const path = hash.replace(/^#/, "");
  const m = /^\/play\/([^/]+)\/?$/.exec(path);
  if (m) return { name: "play", slug: decodeURIComponent(m[1]) };
  return { name: "home" };
}

function mountNotFound(root: HTMLElement): Cleanup {
  root.appendChild(
    h(
      "main",
      { class: "screen screen--center" },
      h(
        "div",
        { class: "center-stack" },
        h("p", { class: "h1 h1--sm" }, "Theme not found"),
        h("a", { href: "#/", class: "btn btn--text" }, "← Themes"),
      ),
    ),
  );
  return () => clear(root);
}

/** Hash router: `#/` → home, `#/play/:slug` → play screen. */
export function startRouter(root: HTMLElement) {
  let cleanup: Cleanup | null = null;

  function render() {
    cleanup?.();
    clear(root);
    window.scrollTo(0, 0);
    const route = parseRoute(location.hash);
    if (route.name === "play") {
      const theme = getThemeBySlug(route.slug);
      cleanup =
        theme && theme.status === "published"
          ? mountPlay(root, theme)
          : mountNotFound(root);
    } else {
      cleanup = mountHome(root);
    }
  }

  window.addEventListener("hashchange", render);
  render();
}
