import type { CardSlot, Tile } from "../domain/types";
import { h, replayClass, svgIcon } from "./dom";
import { prefersReducedMotion } from "./reduced-motion";
import { renderTileArt } from "./tile-art";

export interface TileCellDeps {
  onToggle(slotId: string): void;
  onInfo(tile: Tile): void;
  /** Must return the predetermined replacement synchronously (domain decides, UI animates). */
  onReSpin(slotId: string): { newTile: Tile } | null;
}

export interface TileCellProps {
  slot: CardSlot;
  tile: Tile | null;
  canReSpin: boolean;
  /** Presentation-only candidates cycled during the re-spin animation. */
  spinCandidates: Tile[];
}

export interface TileCell {
  el: HTMLElement;
  update(p: TileCellProps): void;
  destroy(): void;
}

const RARITY_LABEL: Record<Tile["rarityCategory"], string> = {
  common: "C",
  uncommon: "U",
  rare: "R",
};

/** ~1.5s total, decelerating gaps between faces. Must stay separate from outcome logic. */
const SPIN_GAPS = [60, 60, 70, 80, 100, 120, 150, 190, 240, 300];

export function createTileCell(
  initial: TileCellProps,
  deps: TileCellDeps,
): TileCell {
  if (initial.slot.isFree) {
    const el = h(
      "div",
      { class: "tile tile--free", "aria-label": "Free space" },
      "FREE",
    );
    return { el, update() {}, destroy() {} };
  }
  if (!initial.tile) {
    const el = h("div", { class: "tile tile--empty" });
    return { el, update() {}, destroy() {} };
  }

  let props = initial;
  let spinning: Tile | null = null; // currently shown candidate during spin
  let settled = false;
  let artTileId: string | null = null;
  const timers: number[] = [];

  const art = h("div", { class: "tile__art" });
  const labelText = h("p", { class: "tile__label-text" });
  const label = h("div", { class: "tile__label" }, labelText);
  const pip = h("span", { class: "tile__pip" });
  const stampHost = h("div", { class: "tile__stamp-host" });
  const infoBtn = h(
    "button",
    {
      type: "button",
      class: "tile__info",
      onClick: (e: Event) => {
        e.stopPropagation();
        if (spinning === null && props.tile) deps.onInfo(props.tile);
      },
    },
    h("span", { class: "tile__info-chip" }, "i"),
  );
  const respinBtn = h(
    "button",
    {
      type: "button",
      class: "tile__respin",
      "aria-label": "Re-spin this tile",
      onClick: handleReSpin,
    },
    h(
      "span",
      { class: "tile__respin-chip" },
      svgIcon(["M21 12a9 9 0 1 1-2.6-6.4", "M21 3v6h-6"], {
        strokeWidth: 2.5,
        className: "tile__respin-icon",
      }),
    ),
  );

  const el = h(
    "div",
    {
      role: "button",
      tabindex: "0",
      class: "tile",
      "data-testid": `slot-${initial.slot.position}`,
      onClick: handleTap,
      onKeydown: (e: KeyboardEvent) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          handleTap();
        }
      },
    },
    art,
    label,
    pip,
    stampHost,
    infoBtn,
    respinBtn,
  );

  function schedule(fn: () => void, ms: number) {
    timers.push(window.setTimeout(fn, ms));
  }

  function handleTap() {
    if (spinning !== null) return;
    deps.onToggle(props.slot.id);
    replayClass(el, "anim-pop");
  }

  function handleReSpin(e: Event) {
    e.stopPropagation();
    e.preventDefault();
    if (spinning !== null) return;
    const result = deps.onReSpin(props.slot.id); // state updates now; we only animate toward it
    if (!result) return;
    if (prefersReducedMotion()) {
      settled = true;
      render();
      schedule(() => {
        settled = false;
        render();
      }, 400);
      return;
    }
    const seq = props.spinCandidates.filter((c) => c.id !== result.newTile.id);
    let t = 0;
    SPIN_GAPS.forEach((gap, i) => {
      t += gap;
      const candidate = seq[i % Math.max(seq.length, 1)] ?? result.newTile;
      schedule(() => {
        spinning = candidate;
        render();
      }, t);
    });
    schedule(() => {
      spinning = null;
      settled = true;
      render();
      schedule(() => {
        settled = false;
        render();
      }, 400);
    }, t + 200);
    spinning = seq[0] ?? result.newTile;
    render();
  }

  function renderStamp(found: boolean) {
    const has = stampHost.firstChild !== null;
    if (found && !has) {
      stampHost.appendChild(
        h(
          "div",
          { class: "tile__stamp anim-stamp" },
          h(
            "div",
            { class: "tile__stamp-circle" },
            svgIcon(["M5 12l5 5L19 7"], {
              strokeWidth: 3.5,
              stroke: "white",
              className: "tile__stamp-check",
            }),
          ),
        ),
      );
    } else if (!found && has) {
      stampHost.replaceChildren();
    }
  }

  function render() {
    const { slot, tile } = props;
    if (!tile) return;
    const shown = spinning ?? tile;
    const busy = spinning !== null;
    const showReSpin = props.canReSpin && !slot.isFound && !busy;

    el.setAttribute("aria-pressed", String(slot.isFound));
    el.setAttribute(
      "aria-label",
      `${tile.name}${slot.isFound ? ", found" : ""}`,
    );
    el.dataset.found = String(slot.isFound);
    el.classList.toggle("tile--busy", busy);
    el.classList.toggle("anim-settle", settled);

    if (shown.id !== artTileId) {
      artTileId = shown.id;
      art.replaceChildren(renderTileArt(shown, "card"));
    }
    art.classList.toggle("tile__art--found", slot.isFound);

    labelText.textContent = shown.shortName ?? shown.name;
    label.classList.toggle("tile__label--respin", showReSpin);

    pip.setAttribute("aria-label", `Rarity: ${shown.rarityCategory}`);
    pip.className = `tile__pip pip--${shown.rarityCategory}`;
    pip.textContent = RARITY_LABEL[shown.rarityCategory];

    renderStamp(slot.isFound);

    infoBtn.setAttribute("aria-label", `About ${tile.name}`);
    infoBtn.hidden = slot.isFound;

    respinBtn.dataset.testid = `respin-${slot.position}`;
    respinBtn.hidden = !showReSpin;
  }

  render();

  return {
    el,
    update(p) {
      props = p;
      render();
    },
    destroy() {
      timers.forEach(clearTimeout);
      timers.length = 0;
    },
  };
}
