import { h } from "./dom";

export interface OverlayOptions {
  testid: string;
  label?: string;
  labelledBy?: string;
  placement: "center" | "bottom";
  closeOnBackdrop: boolean;
  closeOnEscape: boolean;
  /** Extra class for the panel. */
  panelClass?: string;
  /** Inline style for the backdrop (e.g. a delayed entry animation). */
  backdropStyle?: Partial<CSSStyleDeclaration>;
  /** Extra nodes placed on the backdrop behind the panel (e.g. confetti). */
  behind?: Node[];
  content: Node[];
  onClose?: () => void;
}

export interface Overlay {
  panel: HTMLElement;
  backdrop: HTMLElement;
  close(): void;
}

/**
 * Modal overlay built from plain elements (like the original React app):
 * a fixed backdrop with role=presentation and an inner role=dialog panel.
 */
export function openOverlay(o: OverlayOptions): Overlay {
  const panel = h(
    "div",
    {
      role: "dialog",
      "aria-modal": "true",
      "aria-label": o.label,
      "aria-labelledby": o.labelledBy,
      "data-testid": o.testid,
      class: [
        "overlay__panel",
        o.placement === "bottom" ? "overlay__panel--sheet" : "",
        o.panelClass ?? "",
      ]
        .filter(Boolean)
        .join(" "),
      onClick: (e: Event) => e.stopPropagation(),
    },
    ...o.content,
  );
  const backdrop = h(
    "div",
    {
      role: "presentation",
      class: ["overlay", o.placement === "bottom" ? "overlay--bottom" : ""]
        .filter(Boolean)
        .join(" "),
      style: o.backdropStyle,
      onClick: () => {
        if (o.closeOnBackdrop) close();
      },
    },
    ...(o.behind ?? []),
    panel,
  );

  let closed = false;
  const onKey = (e: KeyboardEvent) => {
    if (e.key === "Escape" && o.closeOnEscape) close();
  };
  window.addEventListener("keydown", onKey);

  const previouslyFocused = document.activeElement as HTMLElement | null;

  function close() {
    if (closed) return;
    closed = true;
    window.removeEventListener("keydown", onKey);
    backdrop.remove();
    previouslyFocused?.focus?.();
    o.onClose?.();
  }

  document.body.appendChild(backdrop);
  panel.querySelector<HTMLElement>("button")?.focus();

  return { panel, backdrop, close };
}
