import type { Tile } from "../domain/types";
import { h } from "./dom";

export type ArtSize = "card" | "detail" | "thumb";

function placeholderOf(tile: Tile): { emoji: string; hue: number } {
  const p = (tile.metadata?.placeholder ?? {}) as {
    emoji?: unknown;
    hue?: unknown;
  };
  return {
    emoji: typeof p.emoji === "string" ? p.emoji : "🐾",
    hue: typeof p.hue === "number" ? p.hue : 30,
  };
}

const PLACEHOLDER_FONT: Record<ArtSize, string> = {
  detail: "clamp(96px, 30vw, 160px)",
  thumb: "20px",
  card: "clamp(22px, 7vw, 40px)",
};

/** Emoji + hue swatch used until real art loads, or when it fails to load. */
export function placeholderArt(tile: Tile, size: ArtSize): HTMLElement {
  const { emoji, hue } = placeholderOf(tile);
  return h(
    "div",
    {
      class: "placeholder",
      "aria-hidden": "true",
      style: {
        background: `radial-gradient(circle at 50% 40%, hsl(${hue} 80% 90%), hsl(${hue} 55% 78%))`,
        fontSize: PLACEHOLDER_FONT[size],
      },
    },
    h("span", { class: "placeholder__emoji" }, emoji),
  );
}

/** Tile illustration: `<img>` for approved art, placeholder otherwise. */
export function renderTileArt(tile: Tile, size: ArtSize = "card"): HTMLElement {
  const img = tile.primaryImage;
  if (!img || !img.approved) return placeholderArt(tile, size);
  const src = size === "detail" ? img.url : (img.thumbnailUrl ?? img.url);
  const el = h("img", {
    src,
    alt: img.altText,
    loading: size === "detail" ? "lazy" : "eager",
    decoding: "async",
    draggable: "false",
    class: size === "detail" ? "tile__img tile__img--detail" : "tile__img",
  });
  el.addEventListener("error", () =>
    el.replaceWith(placeholderArt(tile, size)),
  );
  return el;
}
